// Compare every projected section against the original PausePlanner component.
if(UnityEditor.EditorApplication.isPlaying)throw new System.Exception("Edit Mode required");
var flags=System.Reflection.BindingFlags.Static|System.Reflection.BindingFlags.NonPublic|System.Reflection.BindingFlags.Public;
var hooks=(System.Collections.IDictionary)typeof(EchoSphere.Presentation.VisualDom).GetField("States",flags).GetValue(null);if(hooks.Count!=0)throw new System.Exception("Live hooks present");
var assembly=typeof(EchoSphere.Presentation.NativePauseStatsState).Assembly;
EchoSphere.Presentation.V Scope(string name)=>(EchoSphere.Presentation.V)assembly.GetType("EchoSphere.Presentation.Visual_"+name).GetField("Scope").GetValue(null);
var app=Scope("App");var progression=Scope("sphereProgression");var data=Scope("gameData");
var project=typeof(EchoSphere.Runtime.EchoSphereRuntime).GetMethod("ProjectNativePauseSynergiesState",flags);
var fixtures=Newtonsoft.Json.Linq.JArray.Parse(System.IO.File.ReadAllText(System.IO.Path.Combine(UnityEngine.Application.dataPath,"../../tools/EchoSphere.VisualChecks/source-ui-fixtures.json"))).Where(f=>(string)f["name"]=="PausePlanner").ToArray();
System.Collections.Generic.IEnumerable<Newtonsoft.Json.Linq.JToken> Nodes(Newtonsoft.Json.Linq.JToken v){if(v is Newtonsoft.Json.Linq.JObject){yield return v;foreach(var child in v["children"]??new Newtonsoft.Json.Linq.JArray())foreach(var n in Nodes(child))yield return n;}else if(v is Newtonsoft.Json.Linq.JArray)foreach(var child in v)foreach(var n in Nodes(child))yield return n;}
string Text(Newtonsoft.Json.Linq.JToken v)=>v is Newtonsoft.Json.Linq.JObject?string.Concat((v["children"]??new Newtonsoft.Json.Linq.JArray()).Select(Text)):v is Newtonsoft.Json.Linq.JArray?string.Concat(v.Select(Text)):v.ToString();
string Class(Newtonsoft.Json.Linq.JToken n)=>(string)n["properties"]?["className"]??"";
string Normal(string v)=>System.Text.RegularExpressions.Regex.Replace(v??"",@"\s+"," ").Trim();
Newtonsoft.Json.Linq.JToken Freeze(EchoSphere.Presentation.V v){if(v.Raw is EchoSphere.Presentation.VisualDom.Node n)return new Newtonsoft.Json.Linq.JObject{["tag"]=n.Tag,["properties"]=Newtonsoft.Json.Linq.JToken.Parse(EchoSphere.Presentation.VisualJson.Stringify(n.Properties)),["children"]=new Newtonsoft.Json.Linq.JArray(n.Children.Select(Freeze))};if(v.Raw is System.Collections.Generic.List<EchoSphere.Presentation.V>)return new Newtonsoft.Json.Linq.JArray(v.Items.Select(Freeze));return new Newtonsoft.Json.Linq.JValue(v.Text);}
int checks=0,cases=0;void Require(bool ok,string why){checks++;if(!ok)throw new System.Exception(why);}
var previousIcons=EchoSphere.Presentation.VisualSourceIcons.Data;EchoSphere.Presentation.VisualSourceIcons.Data=EchoSphere.Presentation.VisualJson.Parse(UnityEngine.Resources.Load<UnityEngine.TextAsset>("EchoSphere/SourceUiIcons").text);
var observed=new System.Collections.Generic.HashSet<string>();var rows=new System.Collections.Generic.List<object>();
try{
foreach(var fixture in fixtures)for(int variant=0;variant<8;variant++){
var scene=EchoSphere.Presentation.VisualJson.Parse(fixture["props"]["st"].ToString());var player=scene["player"];bool ru=(string)fixture["props"]["lang"]=="ru";
if(variant>0){player["artifacts"]=EchoSphere.Presentation.VisualJs.Arr();player["sphereBranches"]=EchoSphere.Presentation.VisualJs.Obj();
var abilities=player["abilities"];var branches=player["sphereBranches"];foreach(var link in progression["SPHERE_ABILITY_SYNERGIES"].Items){abilities[link["ability"]]=variant>=3?7:0;if(variant==2||variant==3)branches[link["sphere"]]=link["sphereBranch"];}
player["sphereProgression"]=EchoSphere.Presentation.VisualJs.Obj();var levels=player["sphereProgression"];foreach(var link in progression["SPHERE_ABILITY_SYNERGIES"].Items)levels[link["sphere"]]=variant>=3?7:1;
if(variant==4||variant==6||variant==7)player["artifacts"]=EchoSphere.Presentation.VisualJs.ObjectObject["keys"].Call(data["ARTIFACT_MAP"]);
if(variant==6||variant==7){player["combo"]=6;player["resonanceGeometryKey"]="ring";player["timestopTimer"]=1;var sphereMods=player["sphereMods"];sphereMods["freeze"]=1;var spheres=scene["spheres"];var template=spheres.Items.First();foreach(var type in new[]{"standard","sniper","pulse","prism","orbital","void"}){var copy=EchoSphere.Presentation.VisualJson.Parse(EchoSphere.Presentation.VisualJson.Stringify(template));copy["type"]=type;copy["alive"]=true;spheres["push"].Call(copy);}var enemies=scene["enemies"];for(int k=0;k<4;k++)enemies["push"].Call(EchoSphere.Presentation.VisualJs.Obj("hp",100,"isElite",true));}if(variant==7){foreach(var link in progression["SPHERE_ABILITY_SYNERGIES"].Items)branches[link["sphere"]]=link["sphereBranch"];}if(variant==5)player["artifacts"]=EchoSphere.Presentation.VisualJs.Arr(EchoSphere.Presentation.VisualJs.ObjectObject["keys"].Call(data["ARTIFACT_MAP"]).Items.Where((id,index)=>index%3==0).ToArray());
}
var model=(EchoSphere.Presentation.NativePauseSynergiesState)project.Invoke(null,new object[]{scene,ru});
var translations=EchoSphere.Presentation.VisualJson.Parse(fixture["translations"].ToString());var props=EchoSphere.Presentation.VisualJson.Parse(fixture["props"].ToString());props["st"]=scene;props["tab"]="synergies";props["selectedArtifactSetId"]=EchoSphere.Presentation.VisualJs.Null;props["t"]=EchoSphere.Presentation.VisualJs.Fn(args=>translations[args[0]]);foreach(var key in new[]{"setTab","onResume","onExit","setSelectedArtifactSetId"})props[key]=EchoSphere.Presentation.VisualJs.Fn(args=>default);
Newtonsoft.Json.Linq.JToken tree;EchoSphere.Presentation.VisualDom.BeginFrame();try{tree=Freeze(EchoSphere.Presentation.VisualDom.Component("PausePlanner",app["PausePlanner"],props));EchoSphere.Presentation.VisualDom.EndFrame();}finally{EchoSphere.Presentation.VisualDom.Reset();}
var sections=Nodes(tree).Where(n=>(string)n["tag"]=="section").ToArray();Require(sections.Length==5&&model.Sections.Count==5,"Section count");
for(int i=0;i<5;i++){var section=model.Sections[i];var nodes=Nodes(sections[i]).ToArray();Require(nodes.Any(n=>Class(n).Contains("uppercase tracking-wider")&&Normal(Text(n))==Normal(section.Heading)),"Section heading");var cards=nodes.Where(n=>Class(n).StartsWith("rounded-xl ")).ToArray();Require(cards.Length==section.Cards.Count,"Card count");
for(int j=0;j<cards.Length;j++){var card=section.Cards[j];var descendants=Nodes(cards[j]).ToArray();Require((string)cards[j]["properties"]["key"]==card.Id,"Card order/id");
var name=descendants.First(n=>Class(n)==(card.Diagnostic?"text-[9px] uppercase tracking-[0.12em] text-[#7f9bb8] font-bold":"font-bold text-sm"));Require(Normal(Text(name))==Normal(card.Name),"Card name");
if(card.Diagnostic){var tags=descendants.Where(n=>Class(n)=="rounded-md border border-[#243b55] bg-black/5 px-1.5 py-1 text-[9px] text-[#b6c9de]").ToArray();Require(tags.Length==card.Tags.Count,"Signal count");for(int k=0;k<tags.Length;k++)Require(Text(tags[k])==card.Tags[k].Text,"Signal text");if(tags.Length==0)Require(descendants.Any(n=>Text(n)==model.EmptySignals),"Empty signals");continue;}
Require(descendants.Any(n=>Class(n)=="text-[10px] text-[#b6c9de] mt-1"&&Text(n)==card.Description),"Description");Require(descendants.Any(n=>Class(n).StartsWith("text-[9px]")&&Text(n)==card.Status),"Status");
string cls=Class(cards[j]);Require(cls.Contains("animate-pulse")==card.Pulse,"Pulse flag");Require(card.Tone=="base"?cls.Contains("bg-[#0d1726]"):cls.Contains(card.Tone=="purple"?"bg-[#8064a8]/10":card.Tone=="cyan"?"bg-[#39d8ff]/[.05]":card.Tone=="gold"?"bg-[#ffb84d]/10":"bg-[#63e6ff]/10"),"Card tone");observed.Add(section.Id+":"+card.Status);
if(!string.IsNullOrEmpty(card.Hint))Require(descendants.Any(n=>Class(n)=="text-[10px] text-[#7f9bb8] mt-1"&&Normal(Text(n))==Normal(card.Hint)),"Sphere hint");
if(section.Id=="artifacts"){var tags=descendants.Where(n=>Class(n).StartsWith("px-1.5 py-1 rounded-md text-[9px] border")).ToArray();Require(tags.Length==card.Tags.Count,"Required artifact count");for(int k=0;k<tags.Length;k++){Require(Text(tags[k])==card.Tags[k].Text,"Required artifact name");Require(Class(tags[k]).Contains("bg-[#5a8c4a]/10")==card.Tags[k].Owned,"Required artifact ownership");}}
}}
rows.Add(new{fixture=(string)fixture["label"],variant,cards=model.Sections.Sum(s=>s.Cards.Count)});cases++;
}
var result=Newtonsoft.Json.JsonConvert.SerializeObject(new{status="PASS native synergies display projection / original PausePlanner",cases,checks,observed=observed.OrderBy(x=>x),rows,limits="Data projection only; native view, pulse rendering, interaction and performance not accepted"});UnityEditor.SessionState.SetString("EchoNativePauseSynergies",result);System.IO.File.WriteAllText(System.IO.Path.Combine(UnityEngine.Application.dataPath,"../Temp/native-pause-synergies-evidence.json"),result);return result;
}finally{EchoSphere.Presentation.VisualDom.Reset();EchoSphere.Presentation.VisualSourceIcons.Data=previousIcons;}
